fn mounted_command_record(seq:u64)->CommandLogEntry{let mut empty=String::with_capacity(17);empty.clear();let empty_array=Vec::with_capacity(3);let mut bytes=Vec::with_capacity(31);bytes.extend_from_slice(&[0,3,255]);CommandLogEntry{seq,action_id:format!("action-{seq}"),label:LocalizedLabel::from_fn(|_,locale|format!("{locale:?} α command {seq}")),kind:ActionKind::Shell,timestamp:format!("time-{seq}"),edit_id:Some(format!("parent-{seq}")),child_edit_ids:vec![format!("child α-{seq}"),format!("child β-{seq}")],transition_id:Some(format!("transition-{seq}")),count:3,inverse:Some(InverseAction{action_id:format!("inverse-{seq}"),args:Some(DslValue::Object(vec![("original".to_owned(),DslValue::String(empty)),("emptyArray".to_owned(),DslValue::Array(empty_array)),("nested".to_owned(),DslValue::Array(vec![DslValue::Null,DslValue::Bool(true),DslValue::Bytes(bytes),DslValue::Object(vec![("key".to_owned(),DslValue::String("α 🧪️".to_owned()))])]))]))})}}
#[test]
fn mounted_group_receipt_command_pages_keep_live_prefixes_and_exact_original_inverse_owners(){
    fn grant(birth:usize,release:usize)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:64,maximum_capacity_bytes:birth,maximum_release_bytes:release,maximum_depth:64}}
    fn observe(f:impl FnOnce()->RetainedCloneStep,g:RetainedCloneGrant){let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(f);assert!(step.progress().fits(g));assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));}

    let law:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();
    for row in law["cases"].as_array().unwrap(){let mut log=PagedCommandLog::new();let mut expected=Vec::new();for seq in row["sequences"].as_array().unwrap().iter().map(|v|v.as_u64().unwrap()){
        let mut original=Some(mounted_command_record(seq));assert_eq!(serde_json::to_value(original.as_ref().unwrap().inverse.as_ref().unwrap().args.as_ref().unwrap()).unwrap(),law["inverseArgs"]);let pointer=original.as_ref().unwrap().action_id.as_ptr();expected.push(original.as_ref().unwrap().clone());let(mut append,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||log.prepare_append().unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let birth=append.next_capacity_byte_demand();let g=grant(birth,0);
        observe(||append.admit_step(RetainedCloneGrant{maximum_items:0,..g}),grant(0,0));if birth>0{observe(||append.admit_step(grant(birth-1,0)),grant(0,0));}assert_eq!(log.iter().map(|record|record.seq).collect::<Vec<_>>(),expected[..expected.len()-1].iter().map(|record|record.seq).collect::<Vec<_>>());observe(||append.admit_step(g),g);
        let mut stale=log.prepare_append().unwrap();let stale_grant=grant(stale.next_capacity_byte_demand(),0);observe(||stale.admit_step(stale_grant),stale_grant);let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||log.commit_append(&mut append,&mut original).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(original.is_none());let mut refused=Some(mounted_command_record(seq+1000));let refused_pointer=refused.as_ref().unwrap().action_id.as_ptr();let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||log.commit_append(&mut stale,&mut refused));assert_eq!(result,Err(CommandAppendRefusal::Stale));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(refused.as_ref().unwrap().action_id.as_ptr(),refused_pointer);let release=stale.next_close_byte_demand();observe(||stale.close_step(grant(0,release)),grant(0,release));assert_eq!(log.last_mut().unwrap().action_id.as_ptr(),pointer);assert_eq!(log.iter().cloned().collect::<Vec<_>>(),expected);assert_eq!(log.iter().rev().map(|record|record.seq).collect::<Vec<_>>(),expected.iter().rev().map(|record|record.seq).collect::<Vec<_>>());assert_eq!(log.iter().len(),log.len());
        let mut cancelled=log.prepare_append().unwrap();let g=grant(cancelled.next_capacity_byte_demand(),0);observe(||cancelled.admit_step(g),g);let release=cancelled.next_close_byte_demand();if release>0{observe(||cancelled.close_step(grant(0,release-1)),grant(0,0));}observe(||cancelled.close_step(grant(0,release)),grant(0,release));assert_eq!(log.iter().cloned().collect::<Vec<_>>(),expected);
    }
    for index in 0..log.len(){let mut cursor=log.read_cursor(index).unwrap();assert!(cursor.advance(0).is_none());let mut selected=None;for _ in 0..100000{if let Some(record)=cursor.advance(1){selected=Some(record.seq);break;}}assert_eq!(selected,Some(index as u64+1));}assert_eq!(log.len(),row["records"].as_u64().unwrap()as usize);let mut turns=0;while !log.terminal_is_empty(){assert!(turns<100000);let demand=log.next_close_byte_demand().unwrap();let g=grant(0,demand);observe(||log.close_step(RetainedCloneGrant{maximum_items:0,..g}).unwrap(),grant(0,0));if demand>0{observe(||log.close_step(grant(0,demand-1)).unwrap(),grant(0,0));}observe(||log.close_step(g).unwrap(),g);turns+=1;}assert!(log.is_empty());let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(log));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));println!("[DEBUG] command page8 records={} stableprefix/sequence/reverse/foldfields/inverseNested/emptycapacity retained; allwholephysicalturns exact; decision0/0; cancelledreservation0livechange",row["records"]);
    }
}

#[test]
fn mounted_group_receipt_command_pruning_keeps_exact_shell_and_member_rows_with_funded_hidden_owners(){
    fn grant(birth:usize,release:usize)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:64,maximum_capacity_bytes:birth,maximum_release_bytes:release,maximum_depth:64}}
    fn observe(f:impl FnOnce()->RetainedCloneStep,g:RetainedCloneGrant){let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(f);assert!(step.progress().fits(g));assert_eq!((heap.requested_bytes,heap.released_bytes),(step.progress().retained_capacity_bytes,step.progress().released_bytes));}
    let law:serde_json::Value=serde_json::from_str(include_str!("../🧹️pruning/🧫️fixtures/🔣️.json")).unwrap();
    for case in law["cases"].as_array().unwrap(){let mut log=PagedCommandLog::new();let mut original_pointers=Vec::new();for row in case["rows"].as_array().unwrap(){let mut entry=mounted_command_record(row["seq"].as_u64().unwrap());entry.edit_id=row["editId"].as_str().map(str::to_owned);entry.transition_id=row["transitionId"].as_str().map(str::to_owned);original_pointers.push((entry.seq,entry.action_id.as_ptr()));let mut input=Some(entry);let mut append=log.prepare_append().unwrap();let g=grant(append.next_capacity_byte_demand(),0);observe(||append.admit_step(g),g);let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||log.commit_append(&mut append,&mut input).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}
        let original=log.iter().map(|record|record.seq).collect::<Vec<_>>();
        for stop in 0..=original.len(){let(mut prune,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||log.begin_prune().unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));for _ in 0..stop{if log.prune_current(&prune).unwrap().is_none(){break;}observe(||log.advance_prune(&mut prune,false,grant(0,0)).unwrap(),grant(0,0));assert_eq!(log.iter().map(|record|record.seq).collect::<Vec<_>>(),original);}let(done,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||log.cancel_prune(&mut prune,0).unwrap());assert!(!done);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let(done,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||log.cancel_prune(&mut prune,1).unwrap());assert!(done);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(log.iter().map(|record|record.seq).collect::<Vec<_>>(),original);}
        let mut prune=log.begin_prune().unwrap();let mut turns=0;while let Some(record)=log.prune_current(&prune).unwrap(){assert!(turns<100000);let keep=record.edit_id.as_deref().is_none_or(|id|case["heldEdits"].as_array().unwrap().iter().any(|held|held.as_str()==Some(id)))&&record.transition_id.as_deref().is_none_or(|id|case["heldTransitions"].as_array().unwrap().iter().any(|held|held.as_str()==Some(id)));observe(||log.advance_prune(&mut prune,keep,RetainedCloneGrant{maximum_items:0,..grant(0,0)}).unwrap(),grant(0,0));observe(||log.advance_prune(&mut prune,keep,grant(0,0)).unwrap(),grant(0,0));assert_eq!(log.iter().map(|record|record.seq).collect::<Vec<_>>(),original);turns+=1;}
        let(removed,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||log.commit_prune(&mut prune).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let kept=serde_json::from_value::<Vec<u64>>(case["keptSequences"].clone()).unwrap();assert_eq!(removed,original.len()-kept.len());assert_eq!(log.iter().map(|record|record.seq).collect::<Vec<_>>(),kept);assert_eq!(log.iter().rev().map(|record|record.seq).collect::<Vec<_>>(),kept.iter().rev().copied().collect::<Vec<_>>());for record in log.iter(){assert_eq!(record.action_id.as_ptr(),original_pointers.iter().find(|(seq,_)|*seq==record.seq).unwrap().1);}
        let mut turns=0;while !log.pruned_terminal_is_empty(){assert!(turns<100000);let g=grant(0,log.next_pruned_close_byte_demand().unwrap());observe(||log.close_pruned_step(RetainedCloneGrant{maximum_items:0,..g}).unwrap(),grant(0,0));if g.maximum_release_bytes>0{observe(||log.close_pruned_step(grant(0,g.maximum_release_bytes-1)).unwrap(),grant(0,0));}observe(||log.close_pruned_step(g).unwrap(),g);assert_eq!(log.iter().map(|record|record.seq).collect::<Vec<_>>(),kept);for record in log.iter(){assert_eq!(record.action_id.as_ptr(),original_pointers.iter().find(|(seq,_)|*seq==record.seq).unwrap().1);}turns+=1;}
        for(index,seq)in kept.iter().enumerate(){let mut cursor=log.read_cursor(index).unwrap();let mut observed=None;for _ in 0..100000{if let Some(record)=cursor.advance(1){observed=Some(record.seq);break;}}assert_eq!(observed,Some(*seq));}
        let mut append=log.prepare_append().unwrap();let g=grant(append.next_capacity_byte_demand(),0);observe(||append.admit_step(g),g);let mut next=Some(mounted_command_record(100));let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||log.commit_append(&mut append,&mut next).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(log.last_mut().unwrap().seq,100);let mut prune=log.begin_prune().unwrap();let mut foreign=PagedCommandLog::new();assert_eq!(foreign.commit_prune(&mut prune),Err(CommandAppendRefusal::Foreign));log.cancel_prune(&mut prune,1).unwrap();
        for _ in 0..100000{if log.terminal_is_empty(){break;}let g=grant(0,log.next_close_byte_demand().unwrap());observe(||log.close_step(g).unwrap(),g);}assert!(log.terminal_is_empty());println!("[DEBUG] command prune={} preparedone/item liveprefixunchanged; exactheld/shellrows={kept:?}; originalptrs held; allcancellations0heap; decision0heap; hiddenleaf/page wholephysicalreceipt; futureappend preserved",case["id"]);
    }
}

#[test]
fn mounted_group_receipt_command_mutable_views_invalidate_exact_prune_and_append_seals(){
    let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:64,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:64};let law:serde_json::Value=serde_json::from_str(include_str!("../🧹️pruning/🧫️fixtures/🔣️.json")).unwrap();let mut log=PagedCommandLog::new();let mut first=Some(mounted_command_record(1));first.as_mut().unwrap().edit_id=Some(law["mutationSeal"]["oldEditId"].as_str().unwrap().to_owned());let mut append=log.prepare_append().unwrap();append.admit_step(RetainedCloneGrant{maximum_capacity_bytes:append.next_capacity_byte_demand(),..grant});log.commit_append(&mut append,&mut first).unwrap();
    let mut prune=log.begin_prune().unwrap();log.advance_prune(&mut prune,true,grant).unwrap();let mut append=log.prepare_append().unwrap();append.admit_step(RetainedCloneGrant{maximum_capacity_bytes:append.next_capacity_byte_demand(),..grant});let replacement=Some(law["mutationSeal"]["newEditId"].as_str().unwrap().to_owned());let pointer=log.iter().next().unwrap().action_id.as_ptr();let (displaced,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||std::mem::replace(&mut log.last_mut().unwrap().edit_id,replacement));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(log.iter().next().unwrap().action_id.as_ptr(),pointer);assert_eq!(displaced.as_deref(),law["mutationSeal"]["oldEditId"].as_str());let mut next=Some(mounted_command_record(2));let next_pointer=next.as_ref().unwrap().action_id.as_ptr();let (refusal,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||log.commit_prune(&mut prune));assert_eq!(refusal,Err(CommandAppendRefusal::Stale));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(log.commit_append(&mut append,&mut next),Err(CommandAppendRefusal::Stale));assert_eq!(next.as_ref().unwrap().action_id.as_ptr(),next_pointer);assert_eq!(log.len(),1);log.cancel_prune(&mut prune,1).unwrap();append.close_step(RetainedCloneGrant{maximum_release_bytes:append.next_close_byte_demand(),..grant});for _ in 0..100000{if log.terminal_is_empty(){break;}log.close_step(RetainedCloneGrant{maximum_release_bytes:log.next_close_byte_demand().unwrap(),..grant}).unwrap();}assert!(log.terminal_is_empty());println!("[DEBUG] actual mutable command view kept originalpointer/data while invalidating both readyprune and append seals, deniedsource retained");
}
